// Made from assets/fonts/InstrumentSans-{Regular,Medium,SemiBold}.ttf (feature/quiet-ui) with fonttools: Latin only,
// WOFF2, about 15 KB each. The command, for each weight:
//   pyftsubset InstrumentSans-<Weight>.ttf --flavor=woff2 --name-IDs="*" --layout-features="kern,liga,tnum,case"
//     --unicodes="U+0020-007E,U+00A0-00FF,U+0131,U+0152-0153,U+02C6,U+02DA,U+02DC,U+2013-2014,U+2018-201A,
//                 U+201C-201E,U+2022,U+2026,U+2039-203A,U+2190,U+2192,U+20AC,U+2122"
// Kept as base64 text so the Worker still has no build step and no asset binding (like assets.ts).

function bytes(b64: string): Uint8Array {
  const s = atob(b64);
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

